namespace vmecpp {

class SurfaceGeometry {
 public:
  SurfaceGeometry(const Sizes* s, const FourierBasisFastToroidal* fb,
                  const TangentialPartitioning* tp);

  void update(
      const std::span<const double> rCC, const std::span<const double> rSS,
      const std::span<const double> rSC, const std::span<const double> rCS,
      const std::span<const double> zSC, const std::span<const double> zCS,
      const std::span<const double> zCC, const std::span<const double> zSS,
      int signOfJacobian, bool fullUpdate);

  // [nfp] cos(2 pi / nfp * p)
  Eigen::VectorXd cos_per;

  // [nfp] sin(2 pi / nfp * p)
  Eigen::VectorXd sin_per;

  // [nZeta] cos(phi)
  Eigen::VectorXd cos_phi;

  // [nZeta] sin(phi)
  Eigen::VectorXd sin_phi;

  // -----------------

  // R
  // full surface
  Eigen::VectorXd r1b;

  // dR/dTheta
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd rub;

  // dR/dPhi
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd rvb;

  // Z
  // full surface
  Eigen::VectorXd z1b;

  // dZ/dTheta
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd zub;

  // dZ/dPhi
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd zvb;

  // d^2R/dTheta^2
  // thread-local effective poloidal range (tp->numZT)
  // only needed within SurfaceGeometry() but public for testing
  Eigen::VectorXd ruu;

  // d^2R/(dTheta dPhi)
  // thread-local effective poloidal range (tp->numZT)
  // only needed within SurfaceGeometry() but public for testing
  Eigen::VectorXd ruv;

  // d^2R/dPhi^2
  // thread-local effective poloidal range (tp->numZT)
  // only needed within SurfaceGeometry() but public for testing
  Eigen::VectorXd rvv;

  // d^2Z/dTheta^2
  // thread-local effective poloidal range (tp->numZT)
  // only needed within SurfaceGeometry() but public for testing
  Eigen::VectorXd zuu;

  // d^2Z/(dTheta dPhi)
  // thread-local effective poloidal range (tp->numZT)
  // only needed within SurfaceGeometry() but public for testing
  Eigen::VectorXd zuv;

  // d^2Z/dPhi^2
  // thread-local effective poloidal range (tp->numZT)
  // only needed within SurfaceGeometry() but public for testing
  Eigen::VectorXd zvv;

  // N^r * signOfJacobian
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd snr;

  // N^phi * signOfJacobian
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd snv;

  // N^z * signOfJacobian
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd snz;

  // g_{theta,theta}
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd guu;

  // 2 * g_{theta,zeta} = 2/nfp * g_{theta,phi}
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd guv;

  // g_{zeta,zeta} = 1/(nfp*nfp) g_{phi,phi}
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd gvv;

  // 1/2 d^2X/dTheta^2 dot N
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd auu;

  // d^2X/(dTheta dZeta) dot N
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd auv;

  // 1/2 d^2X/dZeta^2 dot N
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd avv;

  // - (R N^R + Z N^Z)
  // needed for dsave --> (X - X') dot N'
  // thread-local effective poloidal range (tp->numZT)
  Eigen::VectorXd drv;

  // R^2 + Z^2
  // needed for gsave --> |X - X'|^2
  // full surface
  Eigen::VectorXd rzb2;

  // x
  // full surface
  Eigen::VectorXd rcosuv;

  // y
  // full surface
  Eigen::VectorXd rsinuv;

  // Non-stellarator-symmetric (lasym) antisymmetric contributions, computed on
  // the reduced poloidal range and combined with the symmetric parts above to
  // fill the full poloidal range (see inverseDFT). r1b/z1b are full-surface;
  // the derivative arrays are thread-local like their symmetric counterparts.
  // Only needed within SurfaceGeometry() but public for testing, like the
  // symmetric arrays above.
  Eigen::VectorXd r1b_asym;
  Eigen::VectorXd z1b_asym;
  Eigen::VectorXd rub_asym;
  Eigen::VectorXd rvb_asym;
  Eigen::VectorXd zub_asym;
  Eigen::VectorXd zvb_asym;
  Eigen::VectorXd ruu_asym;
  Eigen::VectorXd ruv_asym;
  Eigen::VectorXd rvv_asym;
  Eigen::VectorXd zuu_asym;
  Eigen::VectorXd zuv_asym;
  Eigen::VectorXd zvv_asym;

 private:
  const Sizes& s_;
  const FourierBasisFastToroidal& fb_;
  const TangentialPartitioning& tp_;

  void computeConstants();

  void inverseDFT(const std::span<const double> rCC,
                  const std::span<const double> rSS,
                  const std::span<const double> rSC,
                  const std::span<const double> rCS,
                  const std::span<const double> zSC,
                  const std::span<const double> zCS,
                  const std::span<const double> zCC,
                  const std::span<const double> zSS, bool fullUpdate);

  void derivedSurfaceQuantities(int signOfJacobian, bool fullUpdate);
};

}  // namespace vmecpp

#endif  // VMECPP_FREE_BOUNDARY_SURFACE_GEOMETRY_SURFACE_GEOMETRY_H_


namespace vmecpp {

class ExternalMagneticField {
 public:
  ExternalMagneticField(const Sizes* s, const TangentialPartitioning* tp,
                        const SurfaceGeometry* sg, const MGridProvider* mgrid);

  // Returns kFailedPrecondition if this thread's slice left the vacuum grid.
  [[nodiscard]] absl::Status update(const std::span<const double> rAxis,
                                    const std::span<const double> zAxis,
                                    double netToroidalCurrent);

  // axis geometry around whole machine
  Eigen::VectorXd axisXYZ;
  Eigen::VectorXd surfaceXYZ;
  Eigen::VectorXd bCoilsXYZ;

  // interpolated magnetic field from mgrid
  Eigen::VectorXd interpBr;
  Eigen::VectorXd interpBp;
  Eigen::VectorXd interpBz;

  // interpolated magnetic field from mgrid
  double axis_current;
  Eigen::VectorXd curtorBr;
  Eigen::VectorXd curtorBp;
  Eigen::VectorXd curtorBz;

  // outputs to Nestor
  Eigen::VectorXd bSubU;
  Eigen::VectorXd bSubV;
  Eigen::VectorXd bDotN;

 private:
  // We /can/ use ABSCAB to compute the magnetic field due to the axis current,
  // but since ABSCAB was not optimized for performance (yet),
  // this acutally slows down the overall computation quite a bit.
  // Hence, we offer an option here to use ABSCAB if you really need to,
  // but use the simpler method by default,
  // which is a straightforward implementation of the Hanson-Hirshman 2002
  // paper. Regarding VMEC convergence, this should be not a (relevant) problem,
  // as the axis is usually far away enough from the LCFS.
  // This is evident from a call graph analysis of VMEC++ for a few test cases,
  // where the most part of the ABSCAB calls are spent anyway in the far-field
  // (== standard) cases. NOTE: When changing this, also need to change
  // educational_VMEC branch and re-generate test data; use `master` for
  // ABSCAB-version and `no_abscab_in_belicu` for simple version.
  static constexpr bool kUseAbscabForAxisCurrent = false;

  // For an axisymmetric (nZeta == 1) plasma the toroidal direction is not
  // resolved by the surface grid; the net-toroidal-current axis filament is
  // then replicated over this many equally-spaced toroidal angles to resolve
  // it (educational_VMEC uses nvper = 64 for the tokamak case). For nZeta > 1,
  // nvper is the number of field periods.
  static constexpr int kAxisymmetricToroidalReplication = 64;
  int nvper_;

  const Sizes& s_;
  const TangentialPartitioning& tp_;

  const SurfaceGeometry& sg_;
  const MGridProvider& mgrid_;

  void updateInterpolation();

  // Compute the contribution to the external magnetic field from net toroidal
  // current along magnetic axis. Here, the contribution is computed using
  // ABSCAB.
  void AddAxisCurrentFieldAbscab(const std::span<const double> rAxis,
                                 const std::span<const double> zAxis,
                                 double netToroidalCurrent);

  // Compute the contribution to the external magnetic field from net toroidal
  // current along magnetic axis. Here, this contribution is computed using a
  // straightforward implementation of the Hanson-Hirshman 2002 paper.
  void AddAxisCurrentFieldSimple(const std::span<const double> rAxis,
                                 const std::span<const double> zAxis,
                                 double netToroidalCurrent);

  void covariantAndNormalComponents();
};

}  // namespace vmecpp

#endif  // VMECPP_FREE_BOUNDARY_EXTERNAL_MAGNETIC_FIELD_EXTERNAL_MAGNETIC_FIELD_H_


#include <cmath>

#include "absl/algorithm/container.h"

namespace vmecpp {

ExternalMagneticField::ExternalMagneticField(const Sizes* s,
                                             const TangentialPartitioning* tp,
                                             const SurfaceGeometry* sg,
                                             const MGridProvider* mgrid)
    : s_(*s), tp_(*tp), sg_(*sg), mgrid_(*mgrid) {
  // For an axisymmetric (nZeta == 1) plasma the toroidal direction is not
  // resolved by the surface grid, so the axis-current filament is replicated
  // over nvper equally-spaced toroidal angles (matching educational_VMEC's
  // nvper = 64 for the tokamak); otherwise nvper is the number of field
  // periods.
  nvper_ = (s_.nZeta == 1) ? kAxisymmetricToroidalReplication : s_.nfp;

  // nzeta points per each of the nvper toroidal replications,
  // and then one more point to close the loop
  axisXYZ.resize(3 * (s_.nZeta * nvper_ + 1));

  // thread-local tangential grid point range
  const int numLocal = tp_.ztMax - tp_.ztMin;

  surfaceXYZ.resize(3 * numLocal);
  bCoilsXYZ.resize(3 * numLocal);

  interpBr.resize(numLocal);
  interpBp.resize(numLocal);
  interpBz.resize(numLocal);

  curtorBr.resize(numLocal);
  curtorBp.resize(numLocal);
  curtorBz.resize(numLocal);

  bSubU.resize(numLocal);
  bSubV.resize(numLocal);
  bDotN.resize(numLocal);
}

// rAxis, zAxis are provided over a single module
absl::Status ExternalMagneticField::update(const std::span<const double> rAxis,
                                           const std::span<const double> zAxis,
                                           double netToroidalCurrent) {
#ifdef _OPENMP
#pragma omp barrier
#endif  // _OPENMP

  // Not returned here: the barriers below are collective over the team.
  absl::Status interpolation_status =
      mgrid_.interpolate(tp_.ztMin, tp_.ztMax, s_.nZeta, s_.nZnT, sg_.r1b,
                         sg_.z1b, interpBr, interpBp, interpBz);

#ifdef _OPENMP
#pragma omp barrier
#endif  // _OPENMP

  if (kUseAbscabForAxisCurrent) {
    AddAxisCurrentFieldAbscab(rAxis, zAxis, netToroidalCurrent);
  } else {
    AddAxisCurrentFieldSimple(rAxis, zAxis, netToroidalCurrent);
  }

#ifdef _OPENMP
#pragma omp barrier
#endif  // _OPENMP

  covariantAndNormalComponents();

#ifdef _OPENMP
#pragma omp barrier
#endif  // _OPENMP

  return interpolation_status;
}

// add in contribution from net toroidal current along magnetic axis
void ExternalMagneticField::AddAxisCurrentFieldAbscab(
    const std::span<const double> rAxis, const std::span<const double> zAxis,
    double netToroidalCurrent) {
  // copy over axis geometry in first module
  // and convert to Cartesian coordinates
  for (int k = 0; k < s_.nZeta; ++k) {
    axisXYZ[k * 3 + 0] = rAxis[k] * sg_.cos_phi[k];
    axisXYZ[k * 3 + 1] = rAxis[k] * sg_.sin_phi[k];
    axisXYZ[k * 3 + 2] = zAxis[k];
  }  // k

  // rotate into the other toroidal replications (field periods for a
  // stellarator; for an axisymmetric plasma, nvper equally-spaced angles that
  // resolve the otherwise-unsampled toroidal direction)
  const double omega_per = 2.0 * M_PI / nvper_;
  for (int p = 1; p < nvper_; ++p) {
    const double cos_per = std::cos(omega_per * p);
    const double sin_per = std::sin(omega_per * p);
    for (int k = 0; k < s_.nZeta; ++k) {
      axisXYZ[(p * s_.nZeta + k) * 3 + 0] =
          cos_per * axisXYZ[k * 3 + 0] - sin_per * axisXYZ[k * 3 + 1];
      axisXYZ[(p * s_.nZeta + k) * 3 + 1] =
          sin_per * axisXYZ[k * 3 + 0] + cos_per * axisXYZ[k * 3 + 1];
      axisXYZ[(p * s_.nZeta + k) * 3 + 2] = zAxis[k];
    }  // k
  }  // toroidal replications

  // close the loop
  axisXYZ[s_.nZeta * nvper_ * 3 + 0] = axisXYZ[0];
  axisXYZ[s_.nZeta * nvper_ * 3 + 1] = axisXYZ[1];
  axisXYZ[s_.nZeta * nvper_ * 3 + 2] = axisXYZ[2];

  // convert points on surface into surfaceXYZ
  // TODO(jons): might be useful to have interface in abscab,
  // where x, y and z can be specified as three separate arrays
  // (or transpose points array to remove interleave)
  // NOTE: Cannot use rcosuv, rsinuv here,
  // since they are only needed (and thus update) for a full update!
  for (int kl = tp_.ztMin; kl < tp_.ztMax; ++kl) {
    const int k = kl % s_.nZeta;
    surfaceXYZ[(kl - tp_.ztMin) * 3 + 0] = sg_.r1b[kl] * sg_.cos_phi[k];
    surfaceXYZ[(kl - tp_.ztMin) * 3 + 1] = sg_.r1b[kl] * sg_.sin_phi[k];
    surfaceXYZ[(kl - tp_.ztMin) * 3 + 2] = sg_.z1b[kl];
  }  // kl

  // TODO(jons): use callback for providing Cartesian axis geometry
  // --> VertexSupplier

  // store into member for being able to debug it
  axis_current = netToroidalCurrent;

  // Initialize target storage for axis-current magnetic field to zero,
  // since ABSCAB only adds to whatever is in there.
  // If we don't do this, the axis current contributions effectively pile up,
  // iteration after iteration (don't ask how I know about this...).
  bCoilsXYZ.setZero();

  // compute magnetic field due to line current along magnetic axis
  int numProcessors = 1;  // Nestor itself is already parallelized via OpenMP
  abscab::magneticFieldPolygonFilament(s_.nZeta * nvper_ + 1, axisXYZ.data(),
                                       axis_current, tp_.ztMax - tp_.ztMin,
                                       surfaceXYZ.data(), bCoilsXYZ.data(),
                                       numProcessors);

  // transform bCoilsXYZ into cylindrical coordinates
  for (int kl = tp_.ztMin; kl < tp_.ztMax; ++kl) {
    int k = kl % s_.nZeta;

    double _bX = bCoilsXYZ[3 * (kl - tp_.ztMin) + 0];
    double _bY = bCoilsXYZ[3 * (kl - tp_.ztMin) + 1];
    double _bZ = bCoilsXYZ[3 * (kl - tp_.ztMin) + 2];

    double _bR = sg_.cos_phi[k] * _bX + sg_.sin_phi[k] * _bY;
    double _bP = sg_.cos_phi[k] * _bY - sg_.sin_phi[k] * _bX;

    curtorBr[kl - tp_.ztMin] = _bR;
    curtorBp[kl - tp_.ztMin] = _bP;
    curtorBz[kl - tp_.ztMin] = _bZ;
  }  // kl
}

void ExternalMagneticField::AddAxisCurrentFieldSimple(
    const std::span<const double> rAxis, const std::span<const double> zAxis,
    double netToroidalCurrent) {
  // copy over axis geometry in first module
  // and convert to Cartesian coordinates
  for (int k = 0; k < s_.nZeta; ++k) {
    axisXYZ[k * 3 + 0] = rAxis[k] * sg_.cos_phi[k];
    axisXYZ[k * 3 + 1] = rAxis[k] * sg_.sin_phi[k];
    axisXYZ[k * 3 + 2] = zAxis[k];
  }  // k

  // rotate into the other toroidal replications (field periods for a
  // stellarator; for an axisymmetric plasma, nvper equally-spaced angles that
  // resolve the otherwise-unsampled toroidal direction)
  const double omega_per = 2.0 * M_PI / nvper_;
  for (int p = 1; p < nvper_; ++p) {
    const double cos_per = std::cos(omega_per * p);
    const double sin_per = std::sin(omega_per * p);
    for (int k = 0; k < s_.nZeta; ++k) {
      axisXYZ[(p * s_.nZeta + k) * 3 + 0] =
          cos_per * axisXYZ[k * 3 + 0] - sin_per * axisXYZ[k * 3 + 1];
      axisXYZ[(p * s_.nZeta + k) * 3 + 1] =
          sin_per * axisXYZ[k * 3 + 0] + cos_per * axisXYZ[k * 3 + 1];
      axisXYZ[(p * s_.nZeta + k) * 3 + 2] = zAxis[k];
    }  // k
  }  // toroidal replications

  // close the loop
  axisXYZ[s_.nZeta * nvper_ * 3 + 0] = axisXYZ[0];
  axisXYZ[s_.nZeta * nvper_ * 3 + 1] = axisXYZ[1];
  axisXYZ[s_.nZeta * nvper_ * 3 + 2] = axisXYZ[2];

  // convert points on surface into surfaceXYZ
  // TODO(jons): might be useful to have interface in abscab,
  // where x, y and z can be specified as three separate arrays
  // (or transpose points array to remove interleave)
  // NOTE: Cannot use rcosuv, rsinuv here,
  // since they are only needed (and thus update) for a full update!
  for (int kl = tp_.ztMin; kl < tp_.ztMax; ++kl) {
    const int k = kl % s_.nZeta;
    surfaceXYZ[(kl - tp_.ztMin) * 3 + 0] = sg_.r1b[kl] * sg_.cos_phi[k];
    surfaceXYZ[(kl - tp_.ztMin) * 3 + 1] = sg_.r1b[kl] * sg_.sin_phi[k];
    surfaceXYZ[(kl - tp_.ztMin) * 3 + 2] = sg_.z1b[kl];
  }  // kl

  // store into member for being able to debug it
  axis_current = netToroidalCurrent;

  // -------
  // Here, we have the (static in the context of this method) axis geometry
  // (axisXYZ) as well as the geometry of the evaluation locations (surfaceXYZ)
  // done.
  // -------

  // Initialize target storage for axis-current magnetic field to zero.
  // If we don't do this, the axis current contributions effectively pile up,
  // iteration after iteration (don't ask how I know about this...).
  bCoilsXYZ.setZero();

  // 1.0e-7 == mu0/4 pi
  // NOTE: The factor of 2 comes from the Hanson-Hirshman Biot-Savart formula,
  // which is Eqn. (8) in Hanson & Hirshman (2002) [Physics of Plasmas 9, 4410].
  const double magnetic_field_scale = 1.0e-7 * netToroidalCurrent * 2.0;

  for (int source_index = 0; source_index < s_.nZeta * nvper_; ++source_index) {
    const double segment_dx =
        axisXYZ[(source_index + 1) * 3 + 0] - axisXYZ[source_index * 3 + 0];
    const double segment_dy =
        axisXYZ[(source_index + 1) * 3 + 1] - axisXYZ[source_index * 3 + 1];
    const double segment_dz =
        axisXYZ[(source_index + 1) * 3 + 2] - axisXYZ[source_index * 3 + 2];

    const double segment_length =
        std::sqrt(segment_dx * segment_dx + segment_dy * segment_dy +
                  segment_dz * segment_dz);

    for (int kl = tp_.ztMin; kl < tp_.ztMax; ++kl) {
      const int kl_local = kl - tp_.ztMin;

      const double r_i_x =
          surfaceXYZ[kl_local * 3 + 0] - axisXYZ[source_index * 3 + 0];
      const double r_i_y =
          surfaceXYZ[kl_local * 3 + 1] - axisXYZ[source_index * 3 + 1];
      const double r_i_z =
          surfaceXYZ[kl_local * 3 + 2] - axisXYZ[source_index * 3 + 2];
      const double r_i =
          std::sqrt(r_i_x * r_i_x + r_i_y * r_i_y + r_i_z * r_i_z);

      const double r_f_x =
          surfaceXYZ[kl_local * 3 + 0] - axisXYZ[(source_index + 1) * 3 + 0];
      const double r_f_y =
          surfaceXYZ[kl_local * 3 + 1] - axisXYZ[(source_index + 1) * 3 + 1];
      const double r_f_z =
          surfaceXYZ[kl_local * 3 + 2] - axisXYZ[(source_index + 1) * 3 + 2];
      const double r_f =
          std::sqrt(r_f_x * r_f_x + r_f_y * r_f_y + r_f_z * r_f_z);

      const double r_i_plus_r_f = r_i + r_f;

      const double magnetic_field_magnitude =
          magnetic_field_scale * r_i_plus_r_f /
          (r_i * r_f *
           (r_i_plus_r_f * r_i_plus_r_f - segment_length * segment_length));

      // cross product of L*hat(eps)==dvec with Ri_vec,
      // scaled by magnetic field magnitude
      bCoilsXYZ[kl_local * 3 + 0] +=
          magnetic_field_magnitude * (segment_dy * r_i_z - segment_dz * r_i_y);
      bCoilsXYZ[kl_local * 3 + 1] +=
          magnetic_field_magnitude * (segment_dz * r_i_x - segment_dx * r_i_z);
      bCoilsXYZ[kl_local * 3 + 2] +=
          magnetic_field_magnitude * (segment_dx * r_i_y - segment_dy * r_i_x);
    }  // kl
  }  // source_index

  // -------
  // Here, we have the magnetic field from the axis current (bCoilsXYZ) done.
  // -------

  // transform bCoilsXYZ into cylindrical coordinates
  for (int kl = tp_.ztMin; kl < tp_.ztMax; ++kl) {
    int k = kl % s_.nZeta;

    double _bX = bCoilsXYZ[3 * (kl - tp_.ztMin) + 0];
    double _bY = bCoilsXYZ[3 * (kl - tp_.ztMin) + 1];
    double _bZ = bCoilsXYZ[3 * (kl - tp_.ztMin) + 2];

    double _bR = sg_.cos_phi[k] * _bX + sg_.sin_phi[k] * _bY;
    double _bP = sg_.cos_phi[k] * _bY - sg_.sin_phi[k] * _bX;

    curtorBr[kl - tp_.ztMin] = _bR;
    curtorBp[kl - tp_.ztMin] = _bP;
    curtorBz[kl - tp_.ztMin] = _bZ;
  }  // kl
}

// compute bSubU, bSubV: covariant components of external magnetic field
// and bDotN: normal component of external magnetic field
void ExternalMagneticField::covariantAndNormalComponents() {
  // The surface poloidal/toroidal derivative arrays (rub, zub, rvb, zvb) are
  // stored full-range (offset 0) for lasym and thread-local (offset tp_.ztMin)
  // for the symmetric case, matching SurfaceGeometry::derivedSurfaceQuantities.
  // r1b and the normals snr/snv/snz are always thread-local-agnostic /
  // thread-local respectively, so only the derivative reads need this offset.
  const int derivOffset = s_.lasym ? 0 : tp_.ztMin;
  for (int kl = tp_.ztMin; kl < tp_.ztMax; ++kl) {
    // add contributions together
    // --> helps in debugging to have them separate until here
    double fullBr = interpBr[kl - tp_.ztMin] + curtorBr[kl - tp_.ztMin];
    double fullBp = interpBp[kl - tp_.ztMin] + curtorBp[kl - tp_.ztMin];
    double fullBz = interpBz[kl - tp_.ztMin] + curtorBz[kl - tp_.ztMin];

    // covariant components
    bSubU[kl - tp_.ztMin] =
        fullBr * sg_.rub[kl - derivOffset] + fullBz * sg_.zub[kl - derivOffset];
    bSubV[kl - tp_.ztMin] = fullBr * sg_.rvb[kl - derivOffset] +
                            fullBz * sg_.zvb[kl - derivOffset] +
                            fullBp * sg_.r1b[kl];

    // normal component
    bDotN[kl - tp_.ztMin] =
        -(fullBr * sg_.snr[kl - tp_.ztMin] + fullBp * sg_.snv[kl - tp_.ztMin] +
          fullBz * sg_.snz[kl - tp_.ztMin]);
  }  // kl
}

}  // namespace vmecpp


