#ifndef VMECPP_VMEC_RADIAL_PARTITIONING_RADIAL_PARTITIONING_H_
#define VMECPP_VMEC_RADIAL_PARTITIONING_RADIAL_PARTITIONING_H_

#include <mutex>
#include <vector>


namespace vmecpp {

class RadialPartitioning {
 public:
  RadialPartitioning();

  // perform a collective call of this to figure out which CPUs are needed for
  // the current number of surfaces
  void adjustRadialPartitioning(int num_threads, int thread_id, int ns,
                                bool lfreeb, bool printout = true);

  // get the number of threads currently involved in the plasma calculation
  int get_num_threads() const;

  // get the identifier of the current thread
  int get_thread_id() const;

  // returns true if this thread has the plasma boundary
  bool has_boundary() const;

  // ---------------------------------

  // NOTE:
  //  nsMin* is inclusive (start)
  //  nsMax* is exclusive (one past end)

  // nsMinF-1 if possible
  int nsMinF1;

  // nsMaxF+1 if possible
  int nsMaxF1;

  // ---------------------------------

  // radial start index for half-grid arrays
  int nsMinH;

  // radial (end+1) index for half-grid arrays
  int nsMaxH;

  // ---------------------------------

  // radial start index for interior full-grid arrays
  int nsMinFi;

  // radial (end+1) index for interior full-grid arrays
  int nsMaxFi;

  // ---------------------------------

  // radial start index for full-grid arrays
  int nsMinF;

  // radial (end+1) index for full-grid arrays
  int nsMaxF;

  // ---------------------------------

  // radial (end+1) index for full-grid arrays,
  // always including the last closed flux surface (== boundary)
  int nsMaxFIncludingLcfs;

 private:
  int num_threads_;
  int thread_id_;

  int ns_;
};

}  // namespace vmecpp

#endif  // VMECPP_VMEC_RADIAL_PARTITIONING_RADIAL_PARTITIONING_H_


namespace vmecpp {

class FourierCoeffs {
 public:
  FourierCoeffs(const Sizes* s, const RadialPartitioning* r, int nsMin,
                int nsMax, int ns);
  FourierCoeffs(const FourierCoeffs& other) = default;
  FourierCoeffs(FourierCoeffs&& other) noexcept = default;
  FourierCoeffs& operator=(const FourierCoeffs& other);
  FourierCoeffs& operator=(FourierCoeffs&& other) noexcept;

  void setZero();

  void decomposeInto(FourierCoeffs& m_x, const Eigen::VectorXd& scalxc) const;
  void m1Constraint(double scalingFactor,
                    std::optional<int> jMax = std::nullopt);

  // Zero R and Z coefficients with m >= mpolGeom or n > ntorGeom; lambda is
  // left untouched. On the force, this holds geometry at mpolGeom/ntorGeom
  // while lambda keeps the full mpol/ntor resolution.
  void maskGeometryAbove(int mpolGeom, int ntorGeom);

  // Get the sum of squared coefficients for R and Z.
  // If includeOffset is false, the (0,0)-coefficients for cos(mu)*cos(nv) are
  // left out. The range of flux surface to count in is specified as [nsMinHere,
  // nsMaxHere[ in order to allow to not count stuff twice at the borders in
  // different threads.
  double rzNorm(bool includeOffset, int nsMinHere, int nsMaxHere) const;

  double GetXcElement(int rzl, int basis_index, int j, int n, int m) const;

  int nsMin() const;
  int nsMax() const;

 protected:
  const Sizes& s_;
  const RadialPartitioning& r_;

  const int nsMin_;
  const int nsMax_;
  const int ns;

  // [ns x numFC] R ~ cos(m*theta)*cos(n*zeta)
  Eigen::VectorXd rcc;

  // [ns x numFC] R ~ sin(m*theta)*sin(n*zeta)
  Eigen::VectorXd rss;

  // [ns x numFC] R ~ sin(m*theta)*cos(n*zeta)
  Eigen::VectorXd rsc;

  // [ns x numFC] R ~ cos(m*theta)*sin(n*zeta)
  Eigen::VectorXd rcs;

  //***************/

  // [ns x numFC] Z ~ sin(m*theta)*cos(n*zeta)
  Eigen::VectorXd zsc;

  // [ns x numFC] Z ~ cos(m*theta)*sin(n*zeta)
  Eigen::VectorXd zcs;

  // [ns x numFC] Z ~ cos(m*theta)*cos(n*zeta)
  Eigen::VectorXd zcc;

  // [ns x numFC] Z ~ sin(m*theta)*sin(n*zeta)
  Eigen::VectorXd zss;

  //***************/

  // [ns x numFC] lambda ~ sin(m*theta)*cos(n*zeta)
  Eigen::VectorXd lsc;

  // [ns x numFC] lambda ~ cos(m*theta)*sin(n*zeta)
  Eigen::VectorXd lcs;

  // [ns x numFC] lambda ~ cos(m*theta)*cos(n*zeta)
  Eigen::VectorXd lcc;

  // [ns x numFC] lambda ~ sin(m*theta)*sin(n*zeta)
  Eigen::VectorXd lss;
};

}  // namespace vmecpp

#endif  // VMECPP_VMEC_FOURIER_COEFFICIENTS_FOURIER_COEFFICIENTS_H_


#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

#include "absl/algorithm/container.h"
#include "absl/log/log.h"

namespace vmecpp {

FourierCoeffs::FourierCoeffs(const Sizes* s, const RadialPartitioning* r,
                             int nsMin, int nsMax, int ns)
    : s_(*s), r_(*r), nsMin_(nsMin), nsMax_(nsMax), ns(ns) {
  // cannot use r_.nsMaxFIncludingLcfs since need to still obey nsMax
  int jMaxIncludingBoundary = nsMax;
  if (r_.nsMaxF1 == ns) {
    jMaxIncludingBoundary = ns;
  }

  int num_fc_RZ = (jMaxIncludingBoundary - nsMin) * s_.mpol * (s_.ntor + 1);
  int num_fc_L = (jMaxIncludingBoundary - nsMin) * s_.mpol * (s_.ntor + 1);

  rcc.resize(num_fc_RZ);
  rcc.setZero();
  zsc.resize(num_fc_RZ);
  zsc.setZero();
  lsc.resize(num_fc_L);
  lsc.setZero();
  if (s_.lthreed) {
    rss.resize(num_fc_RZ);
    rss.setZero();
    zcs.resize(num_fc_RZ);
    zcs.setZero();
    lcs.resize(num_fc_L);
    lcs.setZero();
  }
  if (s_.lasym) {
    rsc.resize(num_fc_RZ);
    rsc.setZero();
    zcc.resize(num_fc_RZ);
    zcc.setZero();
    lcc.resize(num_fc_L);
    lcc.setZero();
    if (s_.lthreed) {
      rcs.resize(num_fc_RZ);
      rcs.setZero();
      zss.resize(num_fc_RZ);
      zss.setZero();
      lss.resize(num_fc_L);
      lss.setZero();
    }
  }
}

FourierCoeffs& FourierCoeffs::operator=(const FourierCoeffs& other) {
  if (this != &other) {
    rcc = other.rcc;
    rss = other.rss;
    rsc = other.rsc;
    rcs = other.rcs;
    zsc = other.zsc;
    zcs = other.zcs;
    zcc = other.zcc;
    zss = other.zss;
    lsc = other.lsc;
    lcs = other.lcs;
    lcc = other.lcc;
    lss = other.lss;
  }
  return *this;
}

FourierCoeffs& FourierCoeffs::operator=(FourierCoeffs&& other) noexcept {
  if (this != &other) {
    rcc = std::move(other.rcc);
    rss = std::move(other.rss);
    rsc = std::move(other.rsc);
    rcs = std::move(other.rcs);
    zsc = std::move(other.zsc);
    zcs = std::move(other.zcs);
    zcc = std::move(other.zcc);
    zss = std::move(other.zss);
    lsc = std::move(other.lsc);
    lcs = std::move(other.lcs);
    lcc = std::move(other.lcc);
    lss = std::move(other.lss);
  }
  return *this;
}

int FourierCoeffs::nsMin() const { return nsMin_; }

int FourierCoeffs::nsMax() const { return nsMax_; }

void FourierCoeffs::setZero() {
  absl::c_fill(rcc, 0);
  absl::c_fill(zsc, 0);
  absl::c_fill(lsc, 0);
  if (s_.lthreed) {
    absl::c_fill(rss, 0);
    absl::c_fill(zcs, 0);
    absl::c_fill(lcs, 0);
  }
  if (s_.lasym) {
    absl::c_fill(rsc, 0);
    absl::c_fill(zcc, 0);
    absl::c_fill(lcc, 0);
    if (s_.lthreed) {
      absl::c_fill(rcs, 0);
      absl::c_fill(zss, 0);
      absl::c_fill(lss, 0);
    }
  }
}

/** apply even/odd-m decomposition */
void FourierCoeffs::decomposeInto(FourierCoeffs& m_x,
                                  const Eigen::VectorXd& scalxc) const {
  // TODO(jons): understand correct limits in fixed-boundary vs. free-boundary
  int jMaxIncludingBoundary = nsMax_;
  if (r_.nsMaxF1 == ns) {
    jMaxIncludingBoundary = ns;
  }

  // int jMaxRZ = nsMax;
  int jMaxRZ = jMaxIncludingBoundary;

  for (int jF = nsMin_; jF < jMaxIncludingBoundary; ++jF) {
    for (int m = 0; m < s_.mpol; ++m) {
      for (int n = 0; n < s_.ntor + 1; ++n) {
        int idx_fc = ((jF - nsMin_) * s_.mpol + m) * (s_.ntor + 1) + n;

        int m_parity = m % 2;

        // scalxc is always defined on numFull1
        double scal = scalxc[(jF - r_.nsMinF1) * 2 + m_parity];

        if (jF < jMaxRZ) {
          m_x.rcc[idx_fc] = rcc[idx_fc] * scal;
          m_x.zsc[idx_fc] = zsc[idx_fc] * scal;
        }
        m_x.lsc[idx_fc] = lsc[idx_fc] * scal;
        if (s_.lthreed) {
          if (jF < jMaxRZ) {
            m_x.rss[idx_fc] = rss[idx_fc] * scal;
            m_x.zcs[idx_fc] = zcs[idx_fc] * scal;
          }
          m_x.lcs[idx_fc] = lcs[idx_fc] * scal;
        }
        if (s_.lasym) {
          if (jF < jMaxRZ) {
            m_x.rsc[idx_fc] = rsc[idx_fc] * scal;
            m_x.zcc[idx_fc] = zcc[idx_fc] * scal;
          }
          m_x.lcc[idx_fc] = lcc[idx_fc] * scal;
          if (s_.lthreed) {
            if (jF < jMaxRZ) {
              m_x.rcs[idx_fc] = rcs[idx_fc] * scal;
              m_x.zss[idx_fc] = zss[idx_fc] * scal;
            }
            m_x.lss[idx_fc] = lss[idx_fc] * scal;
          }
        }
      }  // n
    }  // m
  }  // j
}

/** (un)do m=1 constraint to couple R_ss,Z_cs as well as R_sc,Z_cc */
void FourierCoeffs::m1Constraint(double scalingFactor,
                                 std::optional<int> jMax) {
  int nsMaxToUse = nsMax_;
  if (jMax.has_value()) {
    nsMaxToUse = std::min(jMax.value(), nsMaxToUse);
  }

  for (int jF = nsMin_; jF < nsMaxToUse; ++jF) {
    for (int n = 0; n < s_.ntor + 1; ++n) {
      int m = 1;
      int idx_fc = ((jF - nsMin_) * s_.mpol + m) * (s_.ntor + 1) + n;
      if (s_.lthreed) {
        double old_rss = rss[idx_fc];
        rss[idx_fc] = (old_rss + zcs[idx_fc]) * scalingFactor;
        zcs[idx_fc] = (old_rss - zcs[idx_fc]) * scalingFactor;
      }
      if (s_.lasym) {
        double old_rsc = rsc[idx_fc];
        rsc[idx_fc] = (old_rsc + zcc[idx_fc]) * scalingFactor;
        zcc[idx_fc] = (old_rsc - zcc[idx_fc]) * scalingFactor;
      }
    }  // n
  }  // j
}

void FourierCoeffs::maskGeometryAbove(int mpolGeom, int ntorGeom) {
  // Same surface range as decomposeInto (owned slab plus boundary).
  int jMaxIncludingBoundary = nsMax_;
  if (r_.nsMaxF1 == ns) {
    jMaxIncludingBoundary = ns;
  }

  for (int jF = nsMin_; jF < jMaxIncludingBoundary; ++jF) {
    for (int m = 0; m < s_.mpol; ++m) {
      for (int n = 0; n < s_.ntor + 1; ++n) {
        if (m < mpolGeom && n <= ntorGeom) {
          continue;
        }

        int idx_fc = ((jF - nsMin_) * s_.mpol + m) * (s_.ntor + 1) + n;

        rcc[idx_fc] = 0.0;
        zsc[idx_fc] = 0.0;
        if (s_.lthreed) {
          rss[idx_fc] = 0.0;
          zcs[idx_fc] = 0.0;
        }
        if (s_.lasym) {
          rsc[idx_fc] = 0.0;
          zcc[idx_fc] = 0.0;
          if (s_.lthreed) {
            rcs[idx_fc] = 0.0;
            zss[idx_fc] = 0.0;
          }
        }
        // lambda left untouched
      }  // n
    }  // m
  }  // j
}

double FourierCoeffs::rzNorm(bool include_offset, int nsMinHere,
                             int nsMaxHere) const {
  // accumulator for local thread
  double local_norm2 = 0.0;

  for (int jF = nsMinHere; jF < nsMaxHere; ++jF) {
    for (int m = 0; m < s_.mpol; ++m) {
      for (int n = 0; n < s_.ntor + 1; ++n) {
        int idx_fc = ((jF - nsMin_) * s_.mpol + m) * (s_.ntor + 1) + n;

        if (n > 0 || m > 0 || include_offset) {
          local_norm2 += rcc[idx_fc] * rcc[idx_fc];
        }
        local_norm2 += zsc[idx_fc] * zsc[idx_fc];
        if (s_.lthreed) {
          local_norm2 += rss[idx_fc] * rss[idx_fc];
          local_norm2 += zcs[idx_fc] * zcs[idx_fc];
        }
        if (s_.lasym) {
          local_norm2 += rsc[idx_fc] * rsc[idx_fc];
          if (n > 0 || m > 0 || include_offset) {
            local_norm2 += zcc[idx_fc] * zcc[idx_fc];
          }
          if (s_.lthreed) {
            local_norm2 += rcs[idx_fc] * rcs[idx_fc];
            local_norm2 += zss[idx_fc] * zss[idx_fc];
          }
        }
      }  // n
    }  // m
  }  // j

  return local_norm2;
}

double FourierCoeffs::GetXcElement(int rzl, int idx_basis, int jF, int n,
                                   int m) const {
  int idx_fc = ((jF - nsMin_) * s_.mpol + m) * (s_.ntor + 1) + n;

  if (rzl == 0) {
    if (idx_basis == 0) {
      return rcc[idx_fc];
    }
    if (s_.lthreed) {
      if (idx_basis == 1) {
        return rss[idx_fc];
      }
    }
    if (s_.lasym) {
      if ((!s_.lthreed && idx_basis == 1) || (s_.lthreed && idx_basis == 2)) {
        return rsc[idx_fc];
      }
      if (s_.lthreed) {
        if (idx_basis == 3) {
          return rcs[idx_fc];
        }
      }
    }
  } else if (rzl == 1) {
    if (idx_basis == 0) {
      return zsc[idx_fc];
    }
    if (s_.lthreed) {
      if (idx_basis == 1) {
        return zcs[idx_fc];
      }
    }
    if (s_.lasym) {
      if ((!s_.lthreed && idx_basis == 1) || (s_.lthreed && idx_basis == 2)) {
        return zcc[idx_fc];
      }
      if (s_.lthreed) {
        if (idx_basis == 3) {
          return zss[idx_fc];
        }
      }
    }
  } else if (rzl == 2) {
    if (idx_basis == 0) {
      return lsc[idx_fc];
    }
    if (s_.lthreed) {
      if (idx_basis == 1) {
        return lcs[idx_fc];
      }
    }
    if (s_.lasym) {
      if ((!s_.lthreed && idx_basis == 1) || (s_.lthreed && idx_basis == 2)) {
        return lcc[idx_fc];
      }
      if (s_.lthreed) {
        if (idx_basis == 3) {
          return lss[idx_fc];
        }
      }
    }
  }

  std::stringstream error_message;
  error_message << "did not find";
  error_message << " rzl=" << rzl;
  error_message << " idx_basis=" << idx_basis;
  error_message << " jF=" << jF;
  error_message << " n=" << n;
  error_message << " m=" << m;
  LOG(FATAL) << error_message.str();

  __builtin_unreachable();
  return 0.0;
}

}  // namespace vmecpp


